-- 0050_global_medicines.sql — Universal Global Medicine Catalogue & Master Index

CREATE TABLE IF NOT EXISTS global_medicines (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  generic_name TEXT,
  strength TEXT,
  form TEXT,
  category TEXT NOT NULL DEFAULT 'General',
  unit TEXT NOT NULL DEFAULT 'unit',
  default_route TEXT DEFAULT 'oral',
  default_frequency TEXT DEFAULT 'OD',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS global_medicines_identity_key ON global_medicines (
  lower(name),
  coalesce(lower(strength), ''),
  coalesce(lower(form), '')
);
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS global_medicines_name_idx ON global_medicines (lower(name) text_pattern_ops);
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS global_medicines_generic_idx ON global_medicines (lower(generic_name) text_pattern_ops);
--> statement-breakpoint

-- Seed initial master medicines
ON CONFLICT (lower(name), coalesce(lower(strength), ''), coalesce(lower(form), '')) DO NOTHING;
